   111    constexpr Span() : Span(nullptr, 0) {}
   112    constexpr Span(T *ptr, size_t len) : data_(ptr), size_(len) {}
   113
   114    template <size_t N>
   115    constexpr Span(T (&array)[N]) : Span(array, N) {}
